// =====================================================================
//  CONFIGURE AQUI
// =====================================================================
const cfg = {
  calendarId: 'agenda@example.com', // mesmo e-mail do fluxo 01
  fuso: 'America/Sao_Paulo',
  evolutionUrl: 'http://evolution:8080',
  instancia: 'consultorio',
  nomePsicologa: 'Ana',
  enviar24h: true,
  enviar2h: true,
  linkOnline: '',            // link fixo da sala online (ex.: Google Meet). Vazio = "a psicóloga envia o link"
  endereco: 'Rua Exemplo, 123, sala 4 – São Paulo/SP',
  silencioInicio: 21,        // não envia lembretes entre 21h...
  silencioFim: 8,            // ...e 8h
};
const agora = DateTime.now().setZone(cfg.fuso);
if (agora.hour >= cfg.silencioInicio || agora.hour < cfg.silencioFim) return [];
return [{ json: { ...cfg, timeMin: agora.toISO(), timeMax: agora.plus({ hours: 25 }).toISO() } }];

const cfg = $('Config lembretes').first().json;
const tz = cfg.fuso;
const agora = DateTime.now().setZone(tz);
const saida = [];
for (const item of $input.all()) {
  const ev = item.json;
  if (!ev || !ev.id || !ev.start || !ev.start.dateTime || ev.status === 'cancelled') continue;
  const desc = String(ev.description || '').replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, ' ');
  const mTel = desc.match(/WhatsApp:\s*\+?([\d\s().-]{10,20})/i);
  if (!mTel) continue; // só eventos com "WhatsApp: número" na descrição recebem lembrete
  let telefone = mTel[1].replace(/\D/g, '');
  if (telefone.length === 10 || telefone.length === 11) telefone = '55' + telefone;
  const nome = ((desc.match(/Paciente:\s*([^\n]+)/i) || [])[1] || '').trim();
  const primeiroNome = nome.split(/\s+/)[0] || '';
  const modalidade = ((desc.match(/Modalidade:\s*([^\n]+)/i) || [])[1] || '').trim().toLowerCase();

  const inicio = DateTime.fromISO(ev.start.dateTime).setZone(tz).setLocale('pt-BR');
  const horas = inicio.diff(agora, 'hours').hours;
  const criadoHa = ev.created ? inicio.diff(DateTime.fromISO(ev.created), 'hours').hours : 999;
  const quando = inicio.hasSame(agora, 'day') ? 'hoje'
    : inicio.hasSame(agora.plus({ days: 1 }), 'day') ? 'amanhã' : inicio.toFormat('cccc');
  const hora = inicio.toFormat('HH:mm');
  const ola = primeiroNome ? `Olá, ${primeiroNome}!` : 'Olá!';
  const local = modalidade.includes('online')
    ? (cfg.linkOnline ? `Link da sessão: ${cfg.linkOnline}` : 'A sessão será online.')
    : modalidade.includes('presencial') ? `Endereço: ${cfg.endereco}` : '';

  if (cfg.enviar24h && horas > 3 && horas <= 24 && criadoHa >= 26) {
    saida.push({ json: {
      eventId: ev.id, tipo: '24h', inicio: ev.start.dateTime, telefone,
      mensagem: `${ola} 😊 Passando para lembrar da sua sessão com ${cfg.nomePsicologa} *${quando}, ${inicio.toFormat('dd/LL')}, às ${hora}*.` +
        (local ? `\n${local}` : '') +
        `\n\nVocê pode confirmar sua presença respondendo *CONFIRMO*? Se precisar remarcar, é só me avisar por aqui.`,
    } });
  }
  if (cfg.enviar2h && horas > 0 && horas <= 2) {
    saida.push({ json: {
      eventId: ev.id, tipo: '2h', inicio: ev.start.dateTime, telefone,
      mensagem: `${ola} Sua sessão com ${cfg.nomePsicologa} começa às *${hora}*.` + (local ? `\n${local}` : '') + '\n\nAté já!',
    } });
  }
}
return saida;
